	light += ComputePBRLightShadow(normal, lightDelta, viewVector, color, g_LTube_Color[i].rgb, g_LTube_Color[i].w, g_LTube_OriginA[i].w, specularTint, ambient, roughness, metallic, 1.0);
}
	return light;
}

uniform vec4 g_LSpot_Color[1];
uniform vec4 g_LSpot_Origin[1];
uniform vec4 g_LSpot_Direction[1];
uniform vec4 g_LSpot_Exponent[1];
uniform mat4 g_LFeature_ShadowProjection[1];
uniform vec4 g_LFeature_ShadowProjectionTransform[1];
vec3 PerformLighting_V1(vec3 worldPos, vec3 color, vec3 normal, vec3 viewVector, vec3 specularTint, vec3 ambient, float roughness, float metallic)
{
	vec3 light = CAST3(0.0);
{
	const uint i = 0u;
	vec3 lightDelta = g_LSpot_Origin[i].xyz - worldPos;
	vec3 projectedCoords = CalculateProjectedCoords(worldPos, g_LFeature_ShadowProjection[i]);
	vec3 colorCookie = texSample2D(COOKIE_SAMPLER, projectedCoords.xy).rgb;
	light += ComputePBRLightShadow(normal, lightDelta, viewVector, color, g_LSpot_Color[i].rgb * colorCookie, g_LSpot_Color[i].w, g_LSpot_Exponent[i].x, specularTint, ambient, roughness, metallic, 1.0);
}
	return light;
}

