{
	const uint i = 0u;
	vec3 lightDelta = g_LPoint_Origin[i].xyz - worldPos;
	light += ComputePBRLightShadow(normal, lightDelta, viewVector, color, g_LPoint_Color[i].rgb, g_LPoint_Color[i].w, g_LPoint_Origin[i].w, specularTint, ambient, roughness, metallic, 1.0);
}
{
	const uint i = 0u;
	vec3 lightDelta = g_LSpot_Origin[i].xyz - worldPos;
	float spotCookie = -dot(normalize(lightDelta), g_LSpot_Direction[i].xyz);
	spotCookie = smoothstep(g_LSpot_Direction[i].w, g_LSpot_Origin[i].w, spotCookie);
	light += ComputePBRLightShadow(normal, lightDelta, viewVector, color, g_LSpot_Color[i].rgb * spotCookie, g_LSpot_Color[i].w, g_LSpot_Exponent[i].x, specularTint, ambient, roughness, metallic, 1.0);
}
{
	const uint i = 0u;
	vec3 lightDelta = PointSegmentDelta(worldPos, g_LTube_OriginA[i].xyz, g_LTube_OriginB[i].xyz);
	light += ComputePBRLightShadow(normal, lightDelta, viewVector, color, g_LTube_Color[i].rgb, g_LTube_Color[i].w, g_LTube_OriginA[i].w, specularTint, ambient, roughness, metallic, 1.0);
}
{
	const uint i = 0u;
	light += ComputePBRLightShadowInfinite(normal, g_LDirectional_Direction[i].xyz, viewVector, color, g_LDirectional_Color[i].rgb, specularTint, ambient, roughness, metallic, 1.0);
}
	return light;
}

